  setTimeout(adjustHeight, 0);
};
```

---

## 4. `addToHistory` function (lines 118-126)

`addToHistory` is destructured from the `useInputHistory` hook — it's not defined inline in the component:

```tsx
const {
  handleKey: handleHistoryKey,
  add: addToHistory,
  reset: resetHistoryIndex,
} = useInputHistory({
  text,
  setText,
  onHeightChange: () => setTimeout(adjustHeight, 0),
});
```

It's called in `handleSend` (line 151):
```tsx
const handleSend = useMemoizedFn(() => {
  if (isProcessing || (!text.trim() && draftMedia.length === 0)) {
    return;
  }

  addToHistory(text);
  sendMessage(text);
  clearInput();
});
```

---

## 5. `useEffect` that watches `pendingInput` (lines 86-104)

```tsx
// Restore pending input
useEffect(() => {
  if (!pendingInput || isStreaming) {
    return;
  }

  // 只在输入框为空时恢复
  if (text.trim()) {
    return;
  }

  const textContent = Content.getText(pendingInput.content);
  if (textContent) {
    setText(textContent);
    setTimeout(() => {
      textareaRef.current?.focus();
      adjustHeight();
    }, 0);
  }
}, [pendingInput, isStreaming]);
```

There is **no other `useEffect`** that watches `pendingInput` or any store state to restore text. This is the only one.

---

## 6. `useMemoizedFn` import and usage

**Import** (line 2):
```tsx
import { useMemoizedFn } from "ahooks";
```

**Usages** — every event handler/memoized callback uses `useMemoizedFn`:

| Line | Function |
|------|----------|
| 110 | `adjustHeight` |
| 128 | `clearInput` |
| 134 | `removeActiveToken` |
| 146 | `handleSend` |
| 156 | `handleSlashCommand` |
| 161 | `applyMention` |
| 234 | `handleKeyDown` |
| 275 | `handleAddButtonClick` |

Note that `handleChange` (line 264) is **not** wrapped with `useMemoizedFn` — it's a plain arrow function. Also, `handleSelect` (line 271) is a plain arrow function too.
